class ReconciliationLabeler {

    private static final Logger log = Logger.getLogger(ReconciliationLabeler.class.getName());

    // Label transactions 1..n and log each.
    void run(int n) {
        if (n < 1) {
            log.warning("N must be at least 1; nothing to label.");
            return;
        }
        for (int i = 1; i <= n; i++) {
            String tag = label(i);
            log.info(() -> "Txn " + i + " → " + tag);
        }
    }

    // Append approach: handles Fizz, Buzz, and FizzBuzz without a special case.
    String label(int number) {
        StringBuilder sb = new StringBuilder();
        if (number % 3 == 0) sb.append("Fizz");  // multiple of 3
        if (number % 5 == 0) sb.append("Buzz");  // multiple of 5 → appends after Fizz for 15
        // If no rule matched, use the plain number.
        return sb.length() == 0 ? String.valueOf(number) : sb.toString();
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
